                serde_json::from_value(params["backupId"].clone()).map_err(|e| e.to_string())?;
            let bm = state.backup_manager.lock().await;
            bm.sync_backup_to_cloud(&backup_id)
                .await
                .map_err(|e| e.to_string())?;
